+func urlMapper() MapperFunc {
+	return func(ctx *DecodeContext, target reflect.Value) error {
+		url, err := url.Parse(ctx.Scan.PopValue("url"))
+		if err != nil {
+			return err
+		}
+		target.Set(reflect.ValueOf(url))
+		return nil
+	}
+}
