+
+func TestURLMapper(t *testing.T) {
+	var cli struct {
+		URL *url.URL `arg:""`
+	}
+	p := mustNew(t, &cli)
+	_, err := p.Parse([]string{"http://w3.org"})
+	require.NoError(t, err)
+	require.Equal(t, "http://w3.org", cli.URL.String())
+	_, err = p.Parse([]string{":foo"})
+	require.Error(t, err)
+}
